-- DWD dimensions
CREATE TABLE IF NOT EXISTS dwd.dim_date (
    date_key INTEGER PRIMARY KEY,  -- yyyymmdd
    calendar_date DATE NOT NULL UNIQUE,
    year INTEGER,
    quarter INTEGER,
    month INTEGER,
    month_name VARCHAR,
    week INTEGER,
    day_of_week INTEGER,
    day_name VARCHAR,
    is_weekend BOOLEAN,
    is_holiday_period BOOLEAN,
    is_promotion_period BOOLEAN,
    season VARCHAR
);
CREATE TABLE IF NOT EXISTS dwd.dim_geo (
    geo_key VARCHAR PRIMARY KEY,  -- region|state|city
    region VARCHAR NOT NULL,
    state VARCHAR NOT NULL,
    city VARCHAR NOT NULL
);
CREATE TABLE IF NOT EXISTS dwd.dim_customer (
    customer_id VARCHAR NOT NULL,
    geo_key VARCHAR NOT NULL REFERENCES dwd.dim_geo (geo_key),
    customer_state VARCHAR,
    customer_region VARCHAR,
    customer_city VARCHAR,
    customer_created_date DATE,
    PRIMARY KEY (customer_id)
);
-- generator labels (customer_segment, customer_lifecycle_stage) are NOT in dim_customer; lifecycle/segments live in dated snapshot tables
CREATE TABLE IF NOT EXISTS dwd.dim_product (
    product_id VARCHAR NOT NULL,
    product_category VARCHAR,
    product_name VARCHAR,
    product_weight_g BIGINT,
    product_length_cm DOUBLE,
    product_height_cm DOUBLE,
    product_width_cm DOUBLE,
    product_price_base_usd DECIMAL(12,2),
    PRIMARY KEY (product_id)
);
CREATE TABLE IF NOT EXISTS dwd.dim_seller (
    seller_id VARCHAR NOT NULL,
    geo_key VARCHAR NOT NULL REFERENCES dwd.dim_geo (geo_key),
    seller_state VARCHAR,
    seller_region VARCHAR,
    seller_city VARCHAR,
    PRIMARY KEY (seller_id)
);

-- DWD facts
CREATE TABLE IF NOT EXISTS dwd.fact_order (
    order_id VARCHAR NOT NULL,
    customer_id VARCHAR NOT NULL,
    purchase_date_key INTEGER NOT NULL REFERENCES dwd.dim_date (date_key),
    purchase_ts TIMESTAMPTZ,
    approved_ts TIMESTAMPTZ,
    carrier_handoff_ts TIMESTAMPTZ,
    delivered_ts TIMESTAMPTZ,
    estimated_delivery_date DATE,
    order_status VARCHAR,
    merch_usd DECIMAL(18,2) NOT NULL,  -- sum of line item_price_usd
    shipping_usd DECIMAL(18,2) NOT NULL,  -- sum of line item_shipping_usd
    order_value_usd DECIMAL(18,2) NOT NULL,  -- merch + shipping
    item_lines INTEGER NOT NULL,
    payment_value_usd DECIMAL(18,2) NOT NULL,  -- sum of payments, reconciliation only
    payment_rows INTEGER NOT NULL,
    review_score INTEGER,  -- at most one review per order
    review_created_date DATE,
    late_by_date BOOLEAN,  -- delivered date > estimated date; NULL if not delivered
    late_by_days BOOLEAN,  -- generator definition; NULL if not delivered
    PRIMARY KEY (order_id),
    FOREIGN KEY (customer_id) REFERENCES dwd.dim_customer (customer_id)
);
-- validity is time dependent: an order is a valid purchase at as_of iff approved_ts < as_of (transaction-rules-v1)
CREATE TABLE IF NOT EXISTS dwd.fact_order_line (
    order_id VARCHAR NOT NULL,
    order_item_seq BIGINT NOT NULL,
    customer_id VARCHAR NOT NULL,
    purchase_date_key INTEGER NOT NULL REFERENCES dwd.dim_date (date_key),
    product_id VARCHAR,
    seller_id VARCHAR,
    seller_product_id VARCHAR,
    item_price_usd DECIMAL(12,2),
    item_shipping_usd DECIMAL(12,2),
    item_total_usd DECIMAL(12,2),
    PRIMARY KEY (order_id, order_item_seq),
    FOREIGN KEY (order_id) REFERENCES dwd.fact_order (order_id),
    FOREIGN KEY (product_id) REFERENCES dwd.dim_product (product_id),
    FOREIGN KEY (seller_id) REFERENCES dwd.dim_seller (seller_id)
);
CREATE TABLE IF NOT EXISTS dwd.fact_payment (
    order_id VARCHAR NOT NULL,
    payment_seq BIGINT NOT NULL,
    payment_type VARCHAR,
    payment_installments BIGINT,
    payment_value_usd DECIMAL(12,2),
    PRIMARY KEY (order_id, payment_seq),
    FOREIGN KEY (order_id) REFERENCES dwd.fact_order (order_id)
);
CREATE TABLE IF NOT EXISTS dwd.fact_fulfillment (
    order_id VARCHAR NOT NULL,
    shipping_distance_band VARCHAR,
    shipping_zone VARCHAR,
    estimated_delivery_days BIGINT,
    order_shipping_usd DECIMAL(12,2),
    delivery_days_floor INTEGER,  -- recomputed from timestamps
    PRIMARY KEY (order_id),
    FOREIGN KEY (order_id) REFERENCES dwd.fact_order (order_id)
);

-- DWS (built by DW-04/DW-05; additive measures and distinct counts are kept apart)
CREATE TABLE IF NOT EXISTS dws.sales_daily_category_region (
    date_key INTEGER NOT NULL,
    product_category VARCHAR NOT NULL,
    customer_region VARCHAR NOT NULL,
    valid_lines BIGINT NOT NULL,  -- additive
    merch_usd DECIMAL(18,2) NOT NULL,  -- additive
    shipping_usd DECIMAL(18,2) NOT NULL,  -- additive
    orders_containing BIGINT NOT NULL,  -- distinct orders at this grain; NOT additive across categories
    PRIMARY KEY (date_key, product_category, customer_region)
);
CREATE TABLE IF NOT EXISTS dws.customer_daily (
    customer_id VARCHAR NOT NULL,
    date_key INTEGER NOT NULL,
    valid_orders BIGINT NOT NULL,
    merch_usd DECIMAL(18,2) NOT NULL,
    PRIMARY KEY (customer_id, date_key)
);
CREATE TABLE IF NOT EXISTS dws.product_daily (
    product_id VARCHAR NOT NULL,
    date_key INTEGER NOT NULL,
    valid_lines BIGINT NOT NULL,
    merch_usd DECIMAL(18,2) NOT NULL,
    orders_containing BIGINT NOT NULL,
    PRIMARY KEY (product_id, date_key)
);
CREATE TABLE IF NOT EXISTS dws.customer_snapshot (
    customer_id VARCHAR NOT NULL,
    as_of TIMESTAMPTZ NOT NULL,
    feature_window_start TIMESTAMPTZ NOT NULL,
    recency_days DOUBLE,
    frequency_90d BIGINT NOT NULL,
    monetary_90d_usd DECIMAL(18,2) NOT NULL,
    orders_all_time BIGINT NOT NULL,
    merch_all_time_usd DECIMAL(18,2) NOT NULL,
    first_purchase_ts TIMESTAMPTZ,
    tenure_days DOUBLE,
    lifecycle_state VARCHAR,  -- rule-based (EDA-05), never the generator label
    snapshot_version VARCHAR NOT NULL,
    PRIMARY KEY (customer_id, as_of)
);
CREATE TABLE IF NOT EXISTS dws.label_repurchase (
    customer_id VARCHAR NOT NULL,
    as_of TIMESTAMPTZ NOT NULL,
    horizon_days INTEGER NOT NULL,
    y BOOLEAN NOT NULL,
    label_matured_at TIMESTAMPTZ NOT NULL,
    label_version VARCHAR NOT NULL,
    PRIMARY KEY (customer_id, as_of, horizon_days, label_version)
);

-- ADS: views over DWD/DWS defined in sql/ads.sql (DW-06); the AI query layer may read only views listed in meta.allowed_view
CREATE TABLE IF NOT EXISTS meta.allowed_view (view_name VARCHAR PRIMARY KEY, purpose VARCHAR NOT NULL);
